class Solution {
public:
    int deleteGreatestValue(std::vector<std::vector<int>>& grid) {
        for (auto& row : grid) {
            std::sort(row.begin(), row.end());
        }
        int ans = 0;
        int m = grid.size(), n = grid[0].size();
        for (int col = 0; col < n; ++col) {
            int col_max = 0;
            for (int r = 0; r < m; ++r) {
                col_max = std::max(col_max, grid[r][col]);
            }
            ans += col_max;
        }
        return ans;
    }
};

class Solution {
    public int deleteGreatestValue(int[][] grid) {
        for (int[] row : grid) {
            java.util.Arrays.sort(row);
        }
        int ans = 0;
        int m = grid.length, n = grid[0].length;
        for (int col = 0; col < n; col++) {
            int colMax = 0;
            for (int r = 0; r < m; r++) {
                colMax = Math.max(colMax, grid[r][col]);
            }
            ans += colMax;
        }
        return ans;
    }
}

var deleteGreatestValue = function(grid) {
    for (const row of grid) {
        row.sort((a, b) => a - b);
    }
    let ans = 0;
    const m = grid.length, n = grid[0].length;
    for (let col = 0; col < n; col++) {
        let colMax = 0;
        for (let r = 0; r < m; r++) {
            if (grid[r][col] > colMax) colMax = grid[r][col];
        }
        ans += colMax;
    }
    return ans;
};
